    uint32_t a = (uint32_t)__cvta_generic_to_shared(bar), ok;
    asm volatile("{\n.reg .pred p;\n"
                 "mbarrier.try_wait.parity.shared::cta.b64 p, [%1], %2;\n"
                 "selp.u32 %0, 1, 0, p;\n}\n" : "=r"(ok) : "r"(a), "r"(phase));
    return ok != 0;
}
